CREATE OR REPLACE FUNCTION public.lts_card_source_rows_v226(p_user_id uuid)
 RETURNS TABLE(source_id uuid, bank text, family text, card_name text, last4 text, billing_last4 text, posting_date date, purchase_date date, reference_month date, due_date date, provider_status text, amount numeric, description text, category text, category_basis text, installment_number integer, total_installments integer, is_payment boolean, bill_id text, observed_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO ''
 SET "TimeZone" TO 'America/Sao_Paulo'
 SET jit TO 'off'
AS $stub$ BEGIN RETURN QUERY SELECT f.source_id,f.bank,f.family,f.card_name,f.last4,f.billing_last4,f.posting_date,f.purchase_date,f.reference_month,f.due_date,f.provider_status,f.amount,f.description,CASE WHEN d.source_ref IS NOT NULL THEN d.beneficiary||' — '||d.category_label ELSE f.category END,CASE WHEN d.source_ref IS NOT NULL THEN 'user_decision' ELSE f.category_basis END,f.installment_number,f.total_installments,f.is_payment,f.bill_id,f.observed_at FROM public.fixture_card_rows f LEFT JOIN public.lts_v178_review_decision d ON d.user_id=p_user_id AND d.source_table='lts_open_finance_staging' AND d.source_ref=f.source_id::text WHERE p_user_id='11111111-1111-4111-8111-111111111111'; END $stub$;
